#!/usr/bin/env python3
"""Generate a Luau check to paste or run (Studio MCP execute_luau) after importing a batch's FBX files.

  python3 scripts/export/studio_check.py build/props > StudioCheck.luau

The Luau finds each imported mesh by name (SM_<Asset>, or the asset name, anywhere in Workspace),
compares MeshPart.Size to the spec within 0.01 studs, reports texture presence, and prints one
line `@@URK_STUDIO@@ <json>`. It only reads; it changes nothing in the place.
"""
from __future__ import annotations

import json
import sys
from pathlib import Path

TEMPLATE = """--!strict
-- Generated by UltimateRobloxKit scripts/export/studio_check.py. Read-only.
local HttpService = game:GetService("HttpService")
local expected: {[string]: {number}} = HttpService:JSONDecode([[__DATA__]])
local results = {}
for name, size in expected do
	local found: MeshPart? = nil
	for _, inst in workspace:GetDescendants() do
		if inst:IsA("MeshPart") and (inst.Name == "SM_" .. name or inst.Name == name) then
			found = inst
			break
		end
	end
	if not found then
		results[name] = { status = "NOT_IMPORTED" }
	else
		-- Blender X, Y (depth), Z (up) arrive as Roblox X, Z, Y.
		local s = found.Size
		local ok = math.abs(s.X - size[1]) <= 0.01 and math.abs(s.Z - size[2]) <= 0.01 and math.abs(s.Y - size[3]) <= 0.01
		local sa = found:FindFirstChildOfClass("SurfaceAppearance")
		results[name] = {
			status = if ok then "SIZE_OK" else "SIZE_MISMATCH",
			size = { s.X, s.Y, s.Z },
			texture = found.TextureID ~= "" or sa ~= nil,
		}
	end
end
print("@@URK_STUDIO@@ " .. HttpService:JSONEncode(results))
"""


def main(argv):
    if len(argv) != 1:
        print(__doc__)
        return 2
    out = Path(argv[0])
    data = {}
    for layout in sorted(out.glob("*/layout.json")):
        spec = json.loads(layout.read_text())
        data[spec["name"]] = spec["size"]
    if not data:
        print(f"no assets with layout.json under {out}", file=sys.stderr)
        return 1
    print(TEMPLATE.replace("__DATA__", json.dumps(data)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
